package joinprobe

import (
    "encoding/binary"
    "hash/crc32"
    "net"
    "testing"
    "time"

    "github.com/Happy2018new/nemc-tan-lobby-solver/core/sctp"
)

// This test sends one real SCTP INIT generated by the forked code used in
// production over an IN-MEMORY net.Pipe. It must fail if the Go compiler
// overlay was omitted, if IEEE CRC32 was used, or if byte order is wrong.
// It never opens a socket, contacts NetEase, or loads user account data.
func TestForkedSCTPInitHasStandardsCompliantCRC32cWireBytes(t *testing.T) {
    client, server := net.Pipe()
    done := make(chan struct{})
    defer func() {
        _ = client.Close()
        _ = server.Close()
        select {
        case <-done:
        case <-time.After(2 * time.Second):
            t.Error("SCTP local handshake goroutine did not terminate")
        }
    }()

    go func() {
        defer close(done)
        _, _ = sctp.Client(sctp.Config{
            NetConn: client,
            RTOMax: 3000,
        })
    }()

    if err := server.SetReadDeadline(time.Now().Add(5 * time.Second)); err != nil {
        t.Fatal("cannot set local SCTP read deadline")
    }
    packet := make([]byte, 1500)
    n, err := server.Read(packet)
    if err != nil {
        t.Fatalf("local fork SCTP failed to emit INIT: %v", err)
    }
    if n < 20 || packet[12] != 1 {
        t.Fatal("first fork SCTP packet is not an INIT chunk")
    }
    raw := packet[:n]

    // RFC 4960 Section 6.8: Castagnoli polynomial CRC32c. The Go CRC
    // value is transmitted in little-endian order for SCTP's reflected
    // checksum representation.
    checksum := binary.LittleEndian.Uint32(raw[8:12])
    castagnoli := crc32.MakeTable(crc32.Castagnoli)
    expected := crc32.Update(0, castagnoli, raw[0:8])
    expected = crc32.Update(expected, castagnoli, []byte{0, 0, 0, 0})
    expected = crc32.Update(expected, castagnoli, raw[12:])
    if checksum != expected {
        t.Fatal("forked SCTP emitted incorrect INIT CRC32c or checksum byte order")
    }

    ieee := crc32.MakeTable(crc32.IEEE)
    wrongPolynomial := crc32.Update(0, ieee, raw[0:8])
    wrongPolynomial = crc32.Update(wrongPolynomial, ieee, []byte{0, 0, 0, 0})
    wrongPolynomial = crc32.Update(wrongPolynomial, ieee, raw[12:])
    if checksum == wrongPolynomial {
        t.Fatal("forked SCTP still emits the incompatible IEEE CRC32 polynomial")
    }
}
